SELECT rentabilidad_7.deudor AS deudor,   rentabilidad_7.ruta_de_venta AS ruta_de_venta,   SUM(rentabilidad_7.rentabilidad) AS temp_calculation_5560818164729849__3482281234__0_,   SUM(rentabilidad_7.cf) AS temp_calculation_5560818164729849__3669921802__0_ FROM rentabilidad_7 WHERE ((rentabilidad_7.figura = 'Preventa On Premise') AND (rentabilidad_7.sede_foraneo_sintec = 'Sede') AND (rentabilidad_7.zona = 'OC')) GROUP BY rentabilidad_7.deudor,   rentabilidad_7.ruta_de_venta;
